func pathSum(root *TreeNode, sum int) int {
	var count func(node *TreeNode, target int64) int
	count = func(node *TreeNode, target int64) int {
		if node == nil {
			return 0
		}
		res := 0
		if int64(node.Val) == target {
			res = 1
		}
		res += count(node.Left, target-int64(node.Val))
		res += count(node.Right, target-int64(node.Val))
		return res
	}
	if root == nil {
		return 0
	}
	return count(root, int64(sum)) + pathSum(root.Left, sum) + pathSum(root.Right, sum)
}

class TreeNode {
  int val;
  TreeNode left;
  TreeNode right;

  TreeNode(int x) {
    val = x;
  }
}

class Solution {
  private int count(TreeNode node, long target) {
    if (node == null) return 0;
    int res = node.val == target ? 1 : 0;
    res += count(node.left, target - node.val);
    res += count(node.right, target - node.val);
    return res;
  }

  public int pathSum(TreeNode root, int sum) {
    if (root == null) return 0;
    return count(root, sum) + pathSum(root.left, sum) + pathSum(root.right, sum);
  }
}

class Solution:
    def pathSum(self, root: Optional[TreeNode], sum: int) -> int:
        def count(node, target):
            if node is None:
                return 0
            res = 1 if node.val == target else 0
            res += count(node.left, target - node.val)
            res += count(node.right, target - node.val)
            return res

        if root is None:
            return 0
        return count(root, sum) + self.pathSum(root.left, sum) + self.pathSum(root.right, sum)

impl Solution {
  pub fn path_sum(root: Option<Box<TreeNode>>, sum: i32) -> i32 {
    fn count(node: &Option<Box<TreeNode>>, target: i64) -> i32 {
      match node {
        None => 0,
        Some(n) => {
          let mut res = if n.val as i64 == target { 1 } else { 0 };
          res += count(&n.left, target - n.val as i64);
          res += count(&n.right, target - n.val as i64);
          res
        }
      }
    }
    match root {
      None => 0,
      Some(n) => {
        count(&Some(n.clone()), sum as i64)
          + Solution::path_sum(n.left, sum)
          + Solution::path_sum(n.right, sum)
      }
    }
  }
}

const pathSum = (root: TreeNode | null, sum: number): number => {
  const count = (node: TreeNode | null, target: number): number => {
    if (!node) return 0;
    let res = node.val === target ? 1 : 0;
    res += count(node.left, target - node.val);
    res += count(node.right, target - node.val);
    return res;
  };
  if (!root) return 0;
  return count(root, sum) + pathSum(root.left, sum) + pathSum(root.right, sum);
};
